practice.solution:
const votes = ["yes", "no", "yes", "maybe", "yes"];
const counts = {};
for (const vote of votes) {
  counts[vote] = (counts[vote] ?? 0) + 1;
}
console.log(JSON.stringify(counts));

const numbers = [3, 8, 5, 12, 7, 6];
const groups = {};
for (const n of numbers) {
  const key = n % 2 === 0 ? "even" : "odd";
  (groups[key] ??= []).push(n);
}
for (const [parity, group] of Object.entries(groups)) {
  console.log(`${parity}: ${group.join(", ")}`);
}

example.code:
const names = ["ada", "bo", "cy"];
const visitors = names.map((name) => ({ name, visits: 0 }));
console.log(JSON.stringify(visitors));

const employees = [
  { name: "Ben", dept: "sales", age: 45, salary: 90 },
  { name: "Ana", dept: "eng", age: 34, salary: 120 },
  { name: "Cid", dept: "eng", age: 41, salary: 135 },
  { name: "Dee", dept: "ops", age: 29, salary: 80 },
  { name: "Eve", dept: "eng", age: 52, salary: 110 },
  { name: "Fay", dept: "sales", age: 38, salary: 95 },
  { name: "Gus", dept: "sales", age: 27, salary: 70 },
];

const engineers = employees
  .filter((e) => e.dept === "eng")
  .sort((a, b) => b.salary - a.salary)
  .map((e) => e.name);
console.log(`Eng by salary: ${engineers.join(", ")}`);

const senior = employees.find((e) => e.age > 40);
console.log(`First over 40: ${senior.name}`);

const deptCounts = {};
for (const e of employees) {
  deptCounts[e.dept] = (deptCounts[e.dept] ?? 0) + 1;
}
const ranked = Object.entries(deptCounts)
  .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
const [topDept, topCount] = ranked[0];
console.log(`Top dept: ${topDept} (${topCount})`);

