practice.solution:
const titles = ["dune", "emma"];
const readingList = titles.map((title) => ({ title, read: false }));
console.log(JSON.stringify(readingList));

const books = [
  { title: "Klara and the Sun", author: "Ishiguro", year: 2021, pages: 303, genre: "scifi" },
  { title: "Piranesi", author: "Clarke", year: 2020, pages: 272, genre: "fantasy" },
  { title: "A Wizard of Earthsea", author: "Le Guin", year: 1968, pages: 183, genre: "fantasy" },
  { title: "The Dispossessed", author: "Le Guin", year: 1974, pages: 387, genre: "scifi" },
  { title: "Gilead", author: "Robinson", year: 2004, pages: 247, genre: "literary" },
  { title: "Station Eleven", author: "Mandel", year: 2014, pages: 333, genre: "scifi" },
  { title: "Jonathan Strange", author: "Clarke", year: 2004, pages: 782, genre: "fantasy" },
];

const recent = books
  .filter((b) => b.year > 2000)
  .sort((a, b) => a.pages - b.pages)
  .map((b) => b.title);
console.log(`New by pages: ${recent.join(", ")}`);

const leGuin = books.find((b) => b.author === "Le Guin");
console.log(`First Le Guin: ${leGuin.title}`);

const genreCounts = {};
for (const b of books) {
  genreCounts[b.genre] = (genreCounts[b.genre] ?? 0) + 1;
}
const ranked = Object.entries(genreCounts)
  .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
const [topGenre, topCount] = ranked[0];
console.log(`Top genre: ${topGenre} (${topCount})`);
